import React, { useMemo } from 'react';
import { useIntl } from 'react-intl';

import {
  CountryFlag,
  Expandable,
  Legend,
  NoDataYet,
  Skeleton,
  Tag,
} from 'components';
import { BasicContainer } from 'components/BasicContainer';
import { BubbleChart } from 'components/Chart/Bubble';
import { FILTER_MODAL_NAME } from 'components/Filter';
import { CalendarClock } from 'components/icon';
import { useLastDataRefresh } from 'contexts';
import { useScopedModal } from 'contexts/Modal/ModalContext';
import { usePageFilterApplied, useSubFilters } from 'hooks';
import { StyledNoDataYet } from 'shared/Styles';

import { RESOURCE_ALLOCATION_MEDIA_PAGE_NAME } from '../../ResourceAllocationMedia';
import { BubbleHeader } from './components/BubbleChartHeader/BubbleChartHeader';
import { RA_BUBBLE_SUBFILTER } from './constants';
import { useKpiRequests } from './hooks/useKpiRequests';
import {
  hasMediaDrilldownChartData,
  MediaDrilldownChartEntry,
} from './utils/hasMediaDrilldownChartData';
import { hasMediaDrilldownData } from './utils/hasMediaDrilldownData';

export interface MediaDrilldoownProps {
  dataTestId?: string;
}

export const MediaDrilldoown: React.FC<MediaDrilldoownProps> = ({
  dataTestId,
}) => {
  const { formatMessage } = useIntl();
  const { open: openFilterModal } = useScopedModal(FILTER_MODAL_NAME);
  const { isGlobalZone, applied } = usePageFilterApplied(
    RESOURCE_ALLOCATION_MEDIA_PAGE_NAME,
  );
  const { lastDataRefreshKpisFormated } = useLastDataRefresh();
  const lastDataRefresh = lastDataRefreshKpisFormated?.media;
  const { activeSubFilters } = useSubFilters();

  const activeMediaDrilldoownSubfilter = useMemo(
    () => activeSubFilters?.[RA_BUBBLE_SUBFILTER] as string,
    [activeSubFilters],
  );

  const kpiRequests = useKpiRequests();

  const chartData = Object.assign(
    {},
    ...Object.values(kpiRequests.charts).map((chart) => chart.data),
  );
  const loadingCharts = Object.values(kpiRequests.charts).some(
    (chart) => chart.loading,
  );

  const activeKpiKey = activeSubFilters?.kpis as string;
  const activeChartData = chartData?.[activeKpiKey] as
    | MediaDrilldownChartEntry
    | undefined;

  const hasData = hasMediaDrilldownData(chartData);

  const emptyStateTitle = formatMessage({
    id: 'ConnectionsCreativity.ResourceAllocationMedia.MediaDrilldoownTab.emptyState.title',
  });
  const emptyStateDescription = formatMessage({
    id: 'ConnectionsCreativity.ResourceAllocationMedia.MediaDrilldoownTab.emptyState.description',
  });
  const selectCountryLabel = formatMessage({
    id: 'ConnectionsCreativity.ResourceAllocationMedia.MediaDrilldoownTab.selectACountry',
  });

  const countrySelected = applied?.country;

  const showSelectCountryEmptyState =
    !loadingCharts && !isGlobalZone && !countrySelected;
  const showNoDataEmptyState =
    !loadingCharts && !isGlobalZone && Boolean(countrySelected) && !hasData;
  const showChartContent =
    !loadingCharts && !showSelectCountryEmptyState && !showNoDataEmptyState;

  const renderFullPageEmptyState = (withAction: boolean) => (
    <StyledNoDataYet
      data-testid={
        dataTestId ? `${dataTestId}-media-drilldown-empty-state` : undefined
      }
      style={{
        width: '100%',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        padding: '64px 24px',
      }}
    >
      <NoDataYet
        title={emptyStateTitle}
        description={emptyStateDescription}
        illustration="noDataAvailable"
        size="auto"
        dataTestId={dataTestId ? `${dataTestId}-media-drilldown` : undefined}
        action={
          withAction
            ? { label: selectCountryLabel, onClick: openFilterModal }
            : undefined
        }
      />
    </StyledNoDataYet>
  );

  const renderChartContent = (
    chartEntry: MediaDrilldownChartEntry | undefined,
    activeSubfilter: string,
  ) => {
    if (!hasMediaDrilldownChartData(chartEntry)) {
      return (
        <StyledNoDataYet
          data-testid={
            dataTestId
              ? `${dataTestId}-media-drilldown-section-empty-state`
              : undefined
          }
          style={{ height: '580px', width: '1280px' }}
        >
          <NoDataYet
            title={emptyStateTitle}
            description={emptyStateDescription}
            illustration="noDataAvailable"
            size="auto"
            dataTestId={
              dataTestId
                ? `${dataTestId}-media-drilldown-section-empty`
                : undefined
            }
          />
        </StyledNoDataYet>
      );
    }

    return (
      <BubbleChart
        dataTestId={
          dataTestId ? `${dataTestId}-media-drilldown-bubble-chart` : undefined
        }
        data={chartEntry.Chart}
        key={activeSubfilter}
      />
    );
  };

  return (
    <BasicContainer
      header={{
        title: 'Media Drilldown',
        titleSize: 'H2',
        bottomTag: lastDataRefresh ? (
          <Tag Icon={CalendarClock} text={`: ${lastDataRefresh}`} />
        ) : null,
        rightContent: <CountryFlag />,
      }}
      layout={{
        border: 'small',
        headerPadding: 'small',
        bodyPadding: true,
      }}
      data-testid={dataTestId ? `media-drilldown-${dataTestId}` : undefined}
    >
      {showSelectCountryEmptyState && renderFullPageEmptyState(true)}
      {showNoDataEmptyState && renderFullPageEmptyState(false)}

      {(loadingCharts || showChartContent) && (
        <>
          <Expandable.Item
            dataTestId={
              dataTestId
                ? `${dataTestId}-media-drilldown-expandable-item`
                : undefined
            }
            id="media-drilldown"
            expand="none"
            expandedHeaderHeight="72px"
            headerCustomized={<BubbleHeader />}
            expandableChildren={
              <>
                {loadingCharts ? (
                  <Skeleton
                    dataTestId={
                      dataTestId
                        ? `${dataTestId}-media-drilldown-skeleton`
                        : undefined
                    }
                    height="580px"
                    width="1280px"
                    length={1}
                  />
                ) : (
                  renderChartContent(
                    activeChartData,
                    activeMediaDrilldoownSubfilter,
                  )
                )}
              </>
            }
          />
          {!loadingCharts && activeChartData?.Legend ? (
            <Legend
              dataTestId={
                dataTestId ? `${dataTestId}-media-drilldown-legend` : undefined
              }
              legendPosition="left"
              caption={activeChartData.Legend}
            />
          ) : null}
        </>
      )}
    </BasicContainer>
  );
};
